cd /tmp && git -C /Users/marcel.a.n.navarro/Dev/zimmermann-pwa show ec9d161:package-lock.json > lock_before.json && git -C /Users/marcel.a.n.navarro/Dev/zimmermann-pwa show 542ac65:package-lock.json > lock_after.json && node -e '
const b=require("/tmp/lock_before.json").packages, a=require("/tmp/lock_after.json").packages;
const bk=new Set(Object.keys(b)), ak=new Set(Object.keys(a));
const added=[...ak].filter(k=>!bk.has(k));
const removed=[...bk].filter(k=>!ak.has(k));
const changed=[...ak].filter(k=>bk.has(k) && b[k].version!==a[k].version);
console.log("TOTAL packages before:", bk.size, " after:", ak.size);
console.log("\n=== ADDED ("+added.length+") ===");
added.forEach(k=>console.log("  "+k+"  @"+a[k].version+(a[k].dev?"  [dev]":"")+(a[k].optional?" [optional]":"")));
console.log("\n=== REMOVED ("+removed.length+") ===");
removed.forEach(k=>console.log("  "+k+"  @"+b[k].version+(b[k].dev?"  [dev]":"")));
console.log("\n=== VERSION CHANGED ("+changed.length+") ===");
changed.forEach(k=>console.log("  "+k+"  "+b[k].version+" -> "+a[k].version+(a[k].dev?"  [dev]":"")));
'

node -e '
const b=require("/tmp/lock_before.json"), a=require("/tmp/lock_after.json");
for (const [label,l] of [["BEFORE",b],["AFTER",a]]) {
  console.log("=== "+label+" ===");
  console.log("  ts-morph in packages:", Object.keys(l.packages).filter(k=>k.includes("ts-morph")).map(k=>k+"@"+l.packages[k].version).join(", ") || "(none)");
  console.log("  msw in packages:", Object.keys(l.packages).filter(k=>/(^|\/)msw$/.test(k)).map(k=>k+"@"+l.packages[k].version).join(", ") || "(none)");
  const root=l.packages[""];
  console.log("  root deps count:", Object.keys(root.dependencies||{}).length, " devDeps:", Object.keys(root.devDependencies||{}).length);
}
'

node -e '
const a=require("/tmp/lock_after.json").packages;
console.log("=== who requires @mswjs/interceptors / msw-ish, in AFTER lock ===");
for (const [k,v] of Object.entries(a)) {
  const all={...(v.dependencies||{}),...(v.optionalDependencies||{}),...(v.peerDependencies||{})};
  for (const d of Object.keys(all)) {
    if (/mswjs|^msw$|headers-polyfill|strict-event-emitter|until-async|rettime|tagged-tag/.test(d)) {
      console.log("  "+(k||"<root>")+"  ->  "+d+"@"+all[d]+(v.peerDependencies&&v.peerDependencies[d]?"  (peer)":""));
    }
  }
}
console.log();
console.log("=== vitest entry peerDependenciesMeta ===");
const vt=a["node_modules/vitest"];
console.log("vitest version:", vt.version);
console.log("peerDeps:", JSON.stringify(vt.peerDependencies,null,1));
console.log("peerDepsMeta:", JSON.stringify(vt.peerDependenciesMeta,null,1));
'

