for (const [k,v] of Object.entries(a)) {
  const all={...(v.dependencies||{}),...(v.optionalDependencies||{}),...(v.peerDependencies||{})};
  if (all["@inquirer/confirm"]) console.log("  "+(k||"<root>")+" -> @inquirer/confirm@"+all["@inquirer/confirm"]+(v.peerDependencies&&v.peerDependencies["@inquirer/confirm"]?" (peer)":""));
}
console.log();
console.log("=== who depends on @emnapi/* (AFTER vs BEFORE) ===");
for (const [label,l] of [["BEFORE",b],["AFTER",a]]) {
