content.content:
  1	import React from 'react';
  2	import { describe, test, expect, vi, beforeEach } from 'vitest';
  3	import { render, screen, waitFor } from '@testing-library/react';
  4	import { MemoryRouter } from 'react-router-dom';
  5	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
  6	import { useContentfulClient } from 'app/hooks/useContentfulClient';
  7	import type { FooterConfigEntry, FooterNavGroupEntry, LinkEntry, RegionEntry } from 'app/types/contentful';
  8	import FooterContainer, { scopeToRegion } from './index';
  9	
 10	// See footerNavColumn/index.test.tsx's identical mock for why: ZimmIcon pulls in the base SFCC
 11	// icons barrel, which throws under Vitest (SVG imports resolve to raw path strings here).
 12	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
 13	  ZimmIcon: () => null,
 14	}));
 15	
 16	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
 17	  default: vi.fn(),
 18	}));
 19	
 20	vi.mock('app/hooks/useContentfulClient', () => ({
 21	  useContentfulClient: vi.fn(),
 22	}));
 23	
 24	// FooterContainer no longer calls useUiCopy() itself (BottomBar/ZimmSubscribeSection source
 25	// their own microcopy directly — see their own test files). With no UiCopyProvider mounted in
 26	// this render tree, useUiCopy() gracefully degrades to fallback-only text on its own, so no
 27	// mock is needed here for that to behave correctly.
 28	
 29	const mockUseMultiSite = vi.mocked(useMultiSite);
 30	const mockUseContentfulClient = vi.mocked(useContentfulClient);
 31	
 32	// ---------------------------------------------------------------------------
 33	// Fixture builders
 34	// ---------------------------------------------------------------------------
 35	
 36	const makeRegion = (siteId: string): RegionEntry => ({
 37	  sys: { id: `region-${siteId}`, contentType: { sys: { id: 'region' } } },
 38	  fields: { siteId, label: siteId },
 39	});
 40	
 41	const makeLink = (id: string, label: string, regions?: RegionEntry[]): LinkEntry => ({
 42	  sys: { id, contentType: { sys: { id: 'link' } } },
 43	  fields: { label, href: '#', regions },
 44	});
 45	
 46	const makeGroup = (id: string, links: LinkEntry[]): FooterNavGroupEntry => ({
 47	  sys: { id, contentType: { sys: { id: 'footerNavGroup' } } },
 48	  fields: { heading: id, links },
 49	});
 50	
 51	const makeConfig = (id: string, overrides: Partial<FooterConfigEntry['fields']> = {}): FooterConfigEntry => ({
 52	  sys: { id, contentType: { sys: { id: 'footerConfig' } } },
 53	  fields: {
 54	    internalTitle: id,
 55	    navGroups: [makeGroup('group-about', [makeLink('link-1', 'Our Story')])],
 56	    ...overrides,
 57	  },
 58	});
 59	
 60	// ---------------------------------------------------------------------------
 61	// scopeToRegion — pure logic
 62	// ---------------------------------------------------------------------------
 63	
 64	describe('scopeToRegion', () => {
 65	  const auOnly = makeRegion('ZimmermannAU');
 66	  const auLink = makeLink('link-au', 'Book an Appointment', [auOnly]);
 67	  const globalLink = makeLink('link-global', 'Our Story');
 68	
 69	  test('drops a region-scoped link that does not match the current site', () => {
 70	    const config = makeConfig('cfg', { navGroups: [makeGroup('group', [auLink, globalLink])] });
 71	
 72	    const result = scopeToRegion(config, 'ZimmermannUS');
 73	
 74	    expect(result.fields.navGroups[0].fields.links.map((l) => l.sys.id)).toEqual(['link-global']);
 75	  });
 76	
 77	  test('keeps a region-scoped link that matches the current site', () => {
 78	    const config = makeConfig('cfg', { navGroups: [makeGroup('group', [auLink, globalLink])] });
 79	
 80	    const result = scopeToRegion(config, 'ZimmermannAU');
 81	
 82	    expect(result.fields.navGroups[0].fields.links.map((l) => l.sys.id)).toEqual(['link-au', 'link-global']);
 83	  });
 84	
 85	  test('applies the same scoping to legalLinks', () => {
 86	    const config = makeConfig('cfg', { legalLinks: [auLink, globalLink] });
 87	
 88	    const result = scopeToRegion(config, 'ZimmermannUS');
 89	
 90	    expect(result.fields.legalLinks?.map((l) => l.sys.id)).toEqual(['link-global']);
 91	  });
 92	
 93	  test('handles legalLinks being undefined without throwing', () => {
 94	    const config = makeConfig('cfg');
 95	
 96	    expect(() => scopeToRegion(config, 'ZimmermannAU')).not.toThrow();
 97	    expect(scopeToRegion(config, 'ZimmermannAU').fields.legalLinks).toBeUndefined();
 98	  });
 99	
100	  test('preserves non-link fields on each nav group unchanged', () => {
101	    const group = makeGroup('group-contact', [globalLink]);
102	    group.fields.showContactChannels = true;
103	    const config = makeConfig('cfg', { navGroups: [group] });
104	
105	    const result = scopeToRegion(config, 'ZimmermannAU');
106	
107	    expect(result.fields.navGroups[0].fields.heading).toBe('group-contact');
108	    expect(result.fields.navGroups[0].fields.showContactChannels).toBe(true);
109	  });
110	});
111	
112	// ---------------------------------------------------------------------------
113	// FooterContainer — Contentful fetch/resolve integration
114	// ---------------------------------------------------------------------------
115	
116	function mockSite(id: string) {
117	  mockUseMultiSite.mockReturnValue({
118	    site: { id },
119	    buildUrl: (path: string) => path,
120	  });
121	}
122	
123	function mockClient(getEntries: ReturnType<typeof vi.fn>) {
124	  mockUseContentfulClient.mockReturnValue({
125	    client: { getEntries } as never,
126	    previewUnavailable: false,
127	    isPreview: false,
128	  });
129	}
130	
131	function renderContainer() {
132	  return render(
133	    <MemoryRouter>
134	      <FooterContainer />
135	    </MemoryRouter>,
136	  );
137	}
138	
139	describe('FooterContainer', () => {
140	  beforeEach(() => {
141	    vi.clearAllMocks();
142	    mockSite('ZimmermannAU');
143	  });
144	
145	  test('renders nothing while the fetch is pending', async () => {
146	    let resolveFetch: (value: { items: FooterConfigEntry[] }) => void = () => {};
147	    const pending = new Promise<{ items: FooterConfigEntry[] }>((resolve) => {
148	      resolveFetch = resolve;
149	    });
150	    mockClient(vi.fn().mockReturnValue(pending));
151	
152	    const { container } = renderContainer();
153	    expect(container).toBeEmptyDOMElement();
154	
155	    resolveFetch({ items: [makeConfig('cfg')] });
156	    await waitFor(() => expect(screen.getByRole('contentinfo')).toBeInTheDocument());
157	  });
158	
159	  test('renders the resolved footerConfig once the fetch succeeds', async () => {
160	    mockClient(vi.fn().mockResolvedValue({ items: [makeConfig('cfg', { subscribeHeading: 'Keep in Touch' })] }));
161	
162	    renderContainer();
163	
164	    await waitFor(() => expect(screen.getByText('Keep in Touch')).toBeInTheDocument());
165	  });
166	
167	  test('renders nothing when the fetch rejects', async () => {
168	    mockClient(vi.fn().mockRejectedValue(new Error('network down')));
169	
170	    const { container } = renderContainer();
171	
172	    await waitFor(() => expect(container).toBeEmptyDOMElement());
173	  });
174	
175	  test('renders nothing when no footerConfig entry matches the current site', async () => {
176	    const usOnly = makeConfig('cfg-us', { regions: [makeRegion('ZimmermannUS')] });
177	    mockClient(vi.fn().mockResolvedValue({ items: [usOnly] }));
178	
179	    const { container } = renderContainer();
180	
181	    await waitFor(() => expect(container).toBeEmptyDOMElement());
182	  });
183	
184	  test('picks the region-scoped entry over the global one for a matching site', async () => {
185	    const global = makeConfig('cfg-global', { subscribeHeading: 'Global Heading' });
186	    const auScoped = makeConfig('cfg-au', {
187	      subscribeHeading: 'AU Heading',
188	      regions: [makeRegion('ZimmermannAU')],
189	    });
190	    mockClient(vi.fn().mockResolvedValue({ items: [global, auScoped] }));
191	
192	    renderContainer();
193	
194	    await waitFor(() => expect(screen.getByText('AU Heading')).toBeInTheDocument());
195	    expect(screen.queryByText('Global Heading')).not.toBeInTheDocument();
196	  });
197	
198	  test('applies region scoping to the resolved entry before rendering', async () => {
199	    const auOnly = makeRegion('ZimmermannAU');
200	    const group = makeGroup('group', [
201	      makeLink('link-au', 'AU Only Link', [auOnly]),
202	      makeLink('link-global', 'Global Link'),
203	    ]);
204	    mockClient(vi.fn().mockResolvedValue({ items: [makeConfig('cfg', { navGroups: [group] })] }));
205	    mockSite('ZimmermannUS');
206	
207	    renderContainer();
208	
209	    await waitFor(() => expect(screen.getByText('Global Link')).toBeInTheDocument());
210	    expect(screen.queryByText('AU Only Link')).not.toBeInTheDocument();
211	  });
212	
213	  test('renders nothing when no Contentful client is configured', () => {
214	    mockClient(vi.fn());
215	    mockUseContentfulClient.mockReturnValue({ client: null, previewUnavailable: false, isPreview: false });
216	
217	    const { container } = renderContainer();
218	
219	    expect(container).toBeEmptyDOMElement();
220	  });
221	});

