108	
109	  test('error: renders the same alert message as unavailable (component does not distinguish them)', () => {
110	    mockHook({ submitState: 'error' });
111	    render(<ZimmSubscribeSection {...baseProps} />);
112	
113	    expect(screen.getByRole('alert')).toHaveTextContent(/temporarily unavailable/i);
114	  });
115	
116	  test('enableNameCapture=false: never renders the modal, even if the hook reports modalOpen=true', () => {
117	    mockHook({ modalOpen: true });
118	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture={false} />);
119	
120	    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
121	  });
