124	    mockHook({ modalOpen: false });
125	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);
126	
127	    expect(screen.queryByRole('dialog')).not.toBeInTheDocument();
128	  });
129	
130	  test('enableNameCapture=true, modalOpen=true: modal renders', () => {
131	    mockHook({ modalOpen: true });
132	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);
133	
134	    expect(screen.getByRole('dialog')).toBeInTheDocument();
135	  });
136	
137	  test('submitting the email form calls handleEmailSubmit with the typed value', async () => {
138	    const handleEmailSubmit = vi.fn();
139	    mockHook({ handleEmailSubmit });
140	    render(<ZimmSubscribeSection {...baseProps} />);
141	
142	    await userEvent.type(screen.getByRole('textbox', { name: /email/i }), 'shopper@example.com');
143	    await userEvent.click(screen.getByRole('button', { name: /subscribe/i }));
144	
145	    expect(handleEmailSubmit).toHaveBeenCalledWith('shopper@example.com');
146	  });
147	
148	  test('modal continue calls handleModalSubmit with the entered names', async () => {
149	    const handleModalSubmit = vi.fn();
150	    mockHook({ modalOpen: true, handleModalSubmit });
151	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);
152	
153	    await userEvent.click(screen.getByRole('button', { name: 'mock-continue' }));
154	
155	    expect(handleModalSubmit).toHaveBeenCalledWith('Jane', 'Smith');
156	  });
157	
158	  test('uses the CMS-sourced email label and subscribe button text when useUiCopy resolves them', () => {
159	    mockUseUiCopy.mockReturnValue({
