 1	import React from 'react';
 2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
 3	import { ZimmInputAction } from 'app/components/ui-kits/molecules/zimmInputAction';
 4	import { ZimmSubscribeModal } from 'app/components/ui-kits/organisms/zimmSubscribeModal';
 5	import { useSubscribeSection } from 'app/hooks/useSubscribeSection';
 6	import { useUiCopy } from 'app/hooks/useUiCopy';
 7	
 8	const ZIMM_SUBSCRIBE_SECTION_RECIPE = 'ZimmSubscribeSection';
 9	
10	// English fallbacks for useUiCopy() below — not props. Kept as named constants (rather than
11	// inline literals at each t() call) since these are full sentences, not single words.
12	const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
13	const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';
14	
15	type ZimmSubscribeSectionProps = {
16	  heading: string;
17	  body: string;
18	  /** Forces the post-submit success state. For Storybook/tests only. */
19	  initialSubscribed?: boolean;
20	  privacyPolicyHref: string;
21	  /**
22	   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships this
23	   * section as an input plus submit button only, and the modal has no design yet.
24	   */
25	  enableNameCapture?: boolean;
26	};
27	
28	/**
29	 * Newsletter sign-up organism — email capture, the idle/unavailable/success/error state
30	 * machine (owned by useSubscribeSection), and the optional HPC-035 name-capture modal. Extracted
31	 * from the footer so it can be placed on any page, not just the global footer.
32	 *
33	 * Microcopy (labels, button text, status messages) comes from useUiCopy(), not props — it's
34	 * app-wide static content, sourced the same way any component reads translated strings via
35	 * useIntl(), and falls back to the English literals here with no UiCopyProvider mounted
36	 * (Storybook, this component's own tests).
37	 *
38	 * @param props see ZimmSubscribeSectionProps
39	 */
40	export const ZimmSubscribeSection = ({
41	  heading,
42	  body,
43	  initialSubscribed = false,
44	  privacyPolicyHref,
45	  enableNameCapture = false,
46	}: ZimmSubscribeSectionProps) => {
47	  const { submitState, modalOpen, closeModal, handleEmailSubmit, handleModalSubmit } = useSubscribeSection({
48	    initialSubscribed,
49	    enableNameCapture,
50	  });
51	  const styles = useMultiStyleConfig(ZIMM_SUBSCRIBE_SECTION_RECIPE, {});
52	  const { t } = useUiCopy();
53	  const emailLabel = t('footer.subscribe.emailLabel', 'Email');
54	  const subscribeButtonLabel = t('footer.subscribe.buttonLabel', 'Subscribe');
55	  const successMessage = t('footer.subscribe.successMessage', SUBSCRIBE_SUCCESS_MESSAGE);
56	  const unavailableMessage = t('footer.subscribe.unavailableMessage', SUBSCRIBE_UNAVAILABLE_MESSAGE);
57	
58	  return (
59	    <div>
60	      <chakra.p __css={styles.heading}>{heading}</chakra.p>
61	      <chakra.p __css={styles.body}>{body}</chakra.p>
62	      <chakra.div aria-live="polite" __css={styles.control}>
63	        {submitState === 'idle' && (
64	          <ZimmInputAction
65	            label={emailLabel}
66	            type="email"
67	            name="footer-email"
68	            icon="chevron-right"
69	            buttonLabel={subscribeButtonLabel}
70	            inverse
71	            onSubmit={handleEmailSubmit}
72	          />
73	        )}
74	        {submitState === 'success' && <chakra.p __css={styles.success}>{successMessage}</chakra.p>}
75	        {(submitState === 'unavailable' || submitState === 'error') && (
76	          <chakra.p role="alert" __css={styles.error}>
77	            {unavailableMessage}
78	          </chakra.p>
79	        )}
80	      </chakra.div>
81	
82	      {enableNameCapture && (
83	        <ZimmSubscribeModal
84	          isOpen={modalOpen}
85	          onClose={closeModal}
86	          onSubmit={handleModalSubmit}
87	          privacyPolicyHref={privacyPolicyHref}
88	        />
89	      )}
90	    </div>
91	  );
92	};

