// Icon barrel — always import icons from this path.
// Never import directly from the base template icon path.
//
// Zimmermann custom icons are defined in ./zimm.tsx.
// Base template icons are re-exported here with Zimmermann naming where the
// design spec uses a different name (e.g. "Bag" vs "Basket").

export * from './zimm';

// Base template icons used by the Zimmermann design system.
// Aliases map the Zimmermann design token name → base component.
export {
  AccountIcon,
  AccountIcon as ProfileIcon,
  BasketIcon,
  BasketIcon as BagIcon,
  BrandLogo,
  CheckIcon,
  // ChevronDown/Left/Right/Up are NOT re-exported from the base template — they are
  // Zimmermann icons defined in ./zimm.tsx. An explicit re-export here would shadow
  // `export * from './zimm'` above and silently win, restoring the base template's
  // filled chevron over the design system's stroked one.
  CloseIcon,
  HeartIcon,
  HeartIcon as FavouritesIcon,
  HeartSolidIcon,
  HeartSolidIcon as FavouritesSolidIcon,
  InfoIcon,
  LocationIcon,
  HamburgerIcon,
  HamburgerIcon as MenuIcon,
  PlusIcon,
  SearchIcon,
  VisibilityIcon,
  VisibilityIcon as PasswordShowIcon,
  VisibilityOffIcon,
  VisibilityOffIcon as PasswordHideIcon,
  // Base template extras — not in the Zimmermann Figma spec but available for use.
  AlertIcon,
  AmexIcon,

